import subprocess,re
branches=["rachel","monica","phoebe","joey","chandler","ross"]
rows=[]
for b in branches:
    out=subprocess.run(["git","log",f"origin/friend/{b}","--format=%H|%cI"],capture_output=True,text=True).stdout.strip().splitlines()
    for line in out:
        sha,ts=line.split("|")
        body=subprocess.run(["git","show","-s","--format=%B",sha],capture_output=True,text=True).stdout
        if "Friend-Message: 1" in body:
            ep=[l.split(":",1)[1].strip() for l in body.splitlines() if l.startswith("Episode:")][0]
            rows.append((ep,ts,sha,b))
for ep in ["S01/E16","S01/E17"]:
    txt=subprocess.run(["git","show",f"origin/main:{ep}.md"],capture_output=True,text=True).stdout
    have=set(re.findall(r"Source: friend/\w+ @ ([0-9a-f]{40})", txt))
    need={r[2] for r in rows if r[0]==ep}
    print(ep,"labeled",len(need),"filed",len(need&have),"missing",len(need-have))
    for m in sorted(need-have):
        print("   ", [r[3] for r in rows if r[2]==m][0], m[:8])
