import subprocess,re
files=subprocess.run(["git","ls-tree","-r","--name-only","origin/main"],capture_output=True,text=True).stdout.split()
eps=[f for f in files if re.match(r"S\d\d/E\d\d\.md$",f)]
bad=[]
for f in sorted(eps):
    txt=subprocess.run(["git","show",f"origin/main:{f}"],capture_output=True,text=True).stdout
    m=re.match(r"---\n(.*?)\n---\n",txt,re.S)
    if not m: bad.append((f,"no frontmatter")); continue
    fm=m.group(1)
    def g(k):
        mm=re.search(rf'^{k}:\s*(.+)$',fm,re.M); return mm.group(1).strip() if mm else None
    title=g("title"); summary=g("summary"); season=g("season"); episode=g("episode"); status=g("status")
    probs=[]
    if not (title and title.startswith('"') and title.endswith('"')): probs.append("title not quoted")
    if not summary: probs.append("no summary")
    if not season or not episode or not status: probs.append("missing field")
    first_para=[l for l in txt[m.end():].splitlines() if l.strip()]
    if summary and first_para and first_para[0].strip().strip('"')!=summary.strip('"'): probs.append("summary paragraph mismatch")
    if probs: bad.append((f,", ".join(probs)))
print(f"episodes: {len(eps)}; problems: {len(bad)}")
for b in bad: print("  ",b)
